import{_ as n}from"./chunks/image11.B6ai34I9.js";import{_ as i}from"./chunks/image14.X3KdA_b9.js";import{_ as o}from"./chunks/2.BRgDBKom.js";import{_ as r,o as a,c as l,am as s}from"./chunks/framework.CenUaW7a.js";const d="/projects/AiMechaM1/en/advanced-kit/assets/11.1.B0zoVgbY.webp",h="/projects/AiMechaM1/en/advanced-kit/assets/11.2.BfK3x2Q-.webp",t="/projects/AiMechaM1/en/advanced-kit/assets/image78.CS8gUyag.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image79.Ca89r1Kb.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image80.EVvOVcJZ.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image81.BuLPAwWx.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image83.yHIH6lJ9.png",u="data:image/png;base64,",f="/projects/AiMechaM1/en/advanced-kit/assets/image84.YUJBqQnb.png",B=JSON.parse('{"title":"3.11 Lesson 11: Intelligent Line-Following Design","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.11 Lesson 11 Intelligent Line-Following Design.md","filePath":"docs/3. Course materials/3.11 Lesson 11 Intelligent Line-Following Design.md"}'),b={name:"docs/3. Course materials/3.11 Lesson 11 Intelligent Line-Following Design.md"};function w(y,e,v,A,k,P){return a(),l("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-11-lesson-11-intelligent-line-following-design" tabindex="-1">3.11 Lesson 11: Intelligent Line-Following Design <a class="header-anchor" href="#_3-11-lesson-11-intelligent-line-following-design" aria-label="Permalink to &quot;3.11 Lesson 11: Intelligent Line-Following Design&quot;">​</a></h1><h2 id="_3-11-1-lesson-introduction" tabindex="-1">3.11.1 Lesson Introduction <a class="header-anchor" href="#_3-11-1-lesson-introduction" aria-label="Permalink to &quot;3.11.1 Lesson Introduction&quot;">​</a></h2><p>As part of the embodied AI large model curriculum series, this lesson introduces the 6-channel line follower sensor to initiate line-following navigation. Taking inspiration from automotive adaptive cruise control and lane-keeping systems, black line recognition via sensors is used to illustrate driving along preset paths. Following the progression of &quot;Sensor Principles → Calibration → Sensor Array Analysis → Basic Line Following → Optimization,&quot; this lesson covers light detection and calibration, analyzes multi-sensor states, and applies conditional logic to achieve precise line following on an oval track. This lays a solid foundation for advanced line-following and integrated applications.</p><h2 id="_3-11-2-learning-objectives" tabindex="-1">3.11.2 Learning Objectives <a class="header-anchor" href="#_3-11-2-learning-objectives" aria-label="Permalink to &quot;3.11.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the optical sensing principles of the 6-channel line follower sensor, including light reflection differences between black lines and white surfaces, the purpose and methods of calibration, and how the six sensor states determine driving directions.</p><p><strong>2.</strong> Perform sensor calibration, apply both single-channel and all-channel detection commands, and use multi-layer nested if-else statements to implement multi-state line-following logic.</p><p><strong>3.</strong> Develop the ability to map sensor states to motion control, structure complex conditional logic, apply closed-loop feedback systems thinking, and build foundational engineering habits in parameter tuning and performance optimization.</p><p><strong>4.</strong> Recognize the real-world value of path navigation in industrial automation and smart logistics, stimulating curiosity and enabling further exploration in autonomous navigation.</p><h2 id="_3-11-3-preparation" tabindex="-1">3.11.3 Preparation <a class="header-anchor" href="#_3-11-3-preparation" aria-label="Permalink to &quot;3.11.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-wheel robot base × 1</p></li><li><p>Type-C USB data cable × 1</p></li><li><p>Computer running Windows or macOS × 1</p></li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>Sensor Principle Description</strong>:</p><p>The 6-channel line follower sensor uses light-sensitive elements to detect the intensity of light reflected from the ground. Black lines absorb light and produce weak reflections, illuminating the corresponding probe indicator light, whereas white backgrounds reflect strong light and keep the indicator light off. The relative position of the black line is determined by the on-off combination of the six side-by-side probes to adjust the driving direction of the car.</p><p><strong>Sensor Numbering Rule</strong>: The six probes are numbered sequentially from right to left as 1, 2, 3, 4, 5, and 6, with Probe 1 on the far right and Probe 6 on the far left.</p><p><strong>Sensor Calibration Steps</strong>:</p><ol><li><p>Point the probes directly at the white background and long-press the learning key until the indicator lights for Probe 1 and Probe 6 flash.</p></li><li><p>Wait until all probe indicator lights flash, move the sensor over the black line, and press the learning key again.</p></li><li><p>Calibration is complete when the middle two probes flash, and all probe indicator lights subsequently remain steadily lit.</p></li><li><p>Maintain a ground clearance of 8 mm to 16 mm for the probes during operation.</p></li></ol><img loading="lazy" height="540" width="960" src="'+d+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p><strong>Probe State Reference List</strong>:</p><ul><li><p>Straight driving state: Probe 3 and Probe 4 are lit, while all other probes are off.</p></li><li><p>Left turn state: Probe 1 and Probe 2 are lit, or Probe 2 and Probe 3 are lit.</p></li><li><p>Right turn state: Probe 5 and Probe 6 are lit, or Probe 4 and Probe 5 are lit.</p></li></ul><p><strong>Hardware Port</strong>: Connect the front 6-channel line follower sensor to port J.</p><h2 id="_3-11-4-hands-on-project" tabindex="-1">3.11.4 Hands-On Project <a class="header-anchor" href="#_3-11-4-hands-on-project" aria-label="Permalink to &quot;3.11.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project focuses on autonomous line following along an oval trajectory, adopting a closed-loop control architecture of loop detection, state matching, and differential speed adjustment. The sensing layer relies on the 6-channel line follower sensor to continuously scan the ground and feed back probe states in real time. The decision-making layer uses nested conditional judgments to match driving conditions, including straight driving, left turns, and right turns. The execution layer relies on left-right wheel speed differentials to correct the trajectory, keeping both wheel groups at equal speed for straight driving and applying wheel speed differentials for flexible cornering. Continuous loop detection and dynamic adjustments keep the car closely following the black line. The project is divided into a basic version and an optimized version, where the optimized version incorporates additional sensor state combinations for finer and smoother steering control.</p><img loading="lazy" height="540" width="960" src="'+h+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="674" width="1162" src="'+t+'" class="common_img" style="width:700px;aspect-ratio:1162 / 674;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Sensor reading</td><td style="text-align:center;"><img loading="lazy" height="56" width="671" src="'+g+'" class="common_img" style="width:400px;aspect-ratio:671 / 56;"></td><td style="text-align:left;">Determines whether a single specified probe detects a black line.</td></tr><tr><td style="text-align:center;">Sensor reading</td><td style="text-align:center;"><img loading="lazy" height="70" width="829" src="'+c+'" class="common_img" style="width:400px;aspect-ratio:829 / 70;"></td><td style="text-align:left;">Determines the overall combination state of all six probes.</td></tr><tr><td style="text-align:center;">Sensor configuration</td><td style="text-align:center;"><img loading="lazy" height="60" width="776" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:776 / 60;"></td><td style="text-align:left;">Adjusts the detection sensitivity of the sensor.</td></tr><tr><td style="text-align:center;">Differential control</td><td style="text-align:center;"><img loading="lazy" height="143" width="600" src="'+m+'" class="common_img" style="width:400px;aspect-ratio:600 / 143;"></td><td style="text-align:left;">Independently controls the rotational speeds of the left and right wheel groups.</td></tr><tr><td style="text-align:center;">Loop control</td><td style="text-align:center;"><img loading="lazy" height="276" width="415" src="'+n+'" class="common_img" style="width:110px;aspect-ratio:415 / 276;"></td><td style="text-align:left;">Continuously detects the line-following state in a loop.</td></tr><tr><td style="text-align:center;">Conditional judgment</td><td style="text-align:center;"><img loading="lazy" height="627" width="589" src="'+i+'" class="common_img" style="width:110px;aspect-ratio:589 / 627;"></td><td style="text-align:left;">Implements multi-state branching via multi-layer nesting.</td></tr><tr><td style="text-align:center;">Logical operation</td><td style="text-align:center;"><img loading="lazy" height="82" width="236" src="'+u+'" class="common_img" style="width:110px;aspect-ratio:236 / 82;"></td><td style="text-align:left;">Combines multiple probe states into a single condition.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Basic Line Following Program</strong></p><ul><li><p>Trigger condition: Start the program when the A key is short-pressed, running inside an outer repeat forever loop.</p></li><li><p>First-level judgment: When Probe 3 and Probe 4 are lit simultaneously for straight driving. → Set both the left and right wheel groups to drive forward at a constant rotational speed of 40 rpm.</p></li><li><p>Second-level judgment: When Probe 2 and Probe 3 are lit for a slight left deviation. → Set the left wheels to 30 rpm and the right wheels to 60 rpm to fine-tune toward the left.</p></li><li><p>Third-level judgment: When Probe 4 and Probe 5 are lit for a slight right deviation. → Set the left wheels to 60 rpm and the right wheels to 30 rpm to fine-tune toward the right.</p></li><li><p>Fourth-level judgment: When Probe 1 and Probe 2 are lit for a large left deviation. → Set the left wheels to 0 rpm and the right wheels to 60 rpm for a rapid left turn.</p></li><li><p>Fifth-level judgment: When Probe 5 and Probe 6 are lit for a large right deviation. → Set the left wheels to 60 rpm and the right wheels to 0 rpm for a rapid right turn.</p></li><li><p>Overall outcome: The car drives autonomously along the oval black line and automatically corrects its heading whenever it deviates.</p></li></ul><img loading="lazy" height="841" width="590" src="'+f+'" class="common_img" style="width:400px;aspect-ratio:590 / 841;"><p><strong>Task 2: Optimized Line Following Program</strong></p><ul><li><p>Add logical <code>OR</code> blocks to the basic version to merge similar probe states.</p></li><li><p>Straight driving condition: Merge states where Probe 3 and Probe 4 are lit, all probes are off, or other centered states occur into a unified straight-driving branch.</p></li><li><p>Left turn condition: Merge states where Probe 1 and Probe 2 are lit, or Probe 2 and Probe 3 are lit, into a left-turn branch.</p></li><li><p>Right turn condition: Merge states where Probe 4 and Probe 5 are lit, or Probe 5 and Probe 6 are lit, into a right-turn branch.</p></li><li><p>Sharp left turn condition: Configure stronger left-turning power for extreme states such as only Probe 1 being lit.</p></li><li><p>Sharp right turn condition: Configure stronger right-turning power for extreme states such as only Probe 6 being lit.</p></li><li><p>Optimization outcome: Provides more comprehensive probe state coverage, finer steering adjustments, and smoother line following that reduces jitter and track derailment.</p></li></ul><img loading="lazy" height="674" width="1162" src="'+t+'" class="common_img" style="width:800px;aspect-ratio:1162 / 674;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Intelligent Line Following Design</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+o+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-11-5-expansion-and-advancement" tabindex="-1">3.11.5 Expansion and Advancement <a class="header-anchor" href="#_3-11-5-expansion-and-advancement" aria-label="Permalink to &quot;3.11.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Intelligent Line Following with Speed Feedback</strong></p><p>Add adaptive speed control to the line-following program, increasing the rotational speed to 60 rpm on straight segments and reducing the rotational speed to 30 rpm on curves to improve cornering stability. Incorporate RGB LED status indicators, illuminating white for straight driving, blue for left turns, and yellow for right turns, to visualize the driving state.</p><p><strong>Project 2: Intersection Recognition and Route Selection</strong></p><p>Upgrade the map to a complex route featuring intersections and add an all-lit state detection where all six probes lighting up simultaneously indicates arrival at an intersection. Program the car to stop, play a prompt tone upon reaching the intersection, and then select a preset route to continue line following, practicing intersection detection and branching decision logic.</p><h2 id="_3-11-6-q-a" tabindex="-1">3.11.6 Q&amp;A <a class="header-anchor" href="#_3-11-6-q-a" aria-label="Permalink to &quot;3.11.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Which probe indicator lights should normally be lit when the Mecanum-wheel car drives straight ahead?</strong></p><p><strong>Answer</strong>: During normal straight driving, the middle two probes, probe 3 and probe 4, should be lit. Because the black line is positioned directly beneath the center of the car, the middle two probes align with the black line and light up upon detecting black, while the outer probes remain over the white background and stay off. If only probe 2 and probe 3 are lit, the black line is offset to the right, and the car needs to steer left to correct its heading. If probe 4 and probe 5 are lit, the black line is offset to the left, and the car needs to steer right to correct its heading. Having the middle two probes lit represents the ideal straight-driving state.</p><p><strong>Q2: Why must the left motors be set slower and the right motors faster when turning left on an oval track?</strong></p><p><strong>Answer</strong>: During a left turn on an oval track, the left side follows the inner lane with a shorter circumference while the right side follows the outer lane with a longer circumference. Setting the left wheels slower and the right wheels faster matches the path-length difference between the inner and outer lanes, keeping the car aligned with the black line without veering off course. If both sides rotate at the same rotational speed, the inner wheels slip, or the outer wheels lag behind during a turn, causing the car to deviate from the trajectory. This follows the same principle as staggered starting lines on a running track, where inner lanes have shorter distances and therefore start further back, using differential speeds to match curved motion requirements.</p><h2 id="_3-11-7-technical-support-and-discussion" tabindex="-1">3.11.7 Technical Support and Discussion <a class="header-anchor" href="#_3-11-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.11.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',53)])])}const V=r(b,[["render",w]]);export{B as __pageData,V as default};
